import heapq


def countRestrictedPaths(n, roads):
    MOD = 1000000007
    adj = [[] for _ in range(n)]
    for a, b, w in roads:
        adj[a].append((b, w))
        adj[b].append((a, w))
    INF = float('inf')
    dist = [INF] * n
    dist[n - 1] = 0
    heap = [(0, n - 1)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(heap, (d + w, v))
    order = sorted((d, u) for u, d in enumerate(dist) if d < INF)
    ways = [0] * n
    ways[n - 1] = 1
    for d, u in order:
        if u == n - 1:
            continue
        total = 0
        for v, w in adj[u]:
            if dist[v] < d:
                total += ways[v]
        ways[u] = total % MOD
    return ways[0] % MOD
